const client = $('Loop through Clients').item.json;
const allReviews = items.map(i => i.json);
const today = new Date();
const thirtyDaysAgo = new Date(today.getTime() - 30 * 24 * 60 * 60 * 1000);
const sixtyDaysAgo = new Date(today.getTime() - 60 * 24 * 60 * 60 * 1000);

// Filter this client's reviews
const clientReviews = allReviews.filter(r => r.client_name === client.client_name);

// Last 30 days
const thisMonth = clientReviews.filter(r => {
  if (!r.review_date) return false;
  const d = new Date(r.review_date);
  return d >= thirtyDaysAgo;
});

// Previous 30 days
const lastMonth = clientReviews.filter(r => {
  if (!r.review_date) return false;
  const d = new Date(r.review_date);
  return d >= sixtyDaysAgo && d < thirtyDaysAgo;
});

const calcAvg = (reviews) => {
  if (reviews.length === 0) return 0;
  const sum = reviews.reduce((acc, r) => acc + (parseFloat(r.star_rating) || 0), 0);
  return (sum / reviews.length).toFixed(1);
};

const thisMonthAvg = calcAvg(thisMonth);
const lastMonthAvg = calcAvg(lastMonth);
const diff = parseFloat(thisMonthAvg) - parseFloat(lastMonthAvg);
let trend = 'Stable';
if (diff > 0.1) trend = 'Improving';
if (diff < -0.1) trend = 'Declining';

// Best review this month
const fiveStars = thisMonth.filter(r => parseInt(r.star_rating) === 5);
const bestReview = fiveStars.length > 0 ? fiveStars[0].review_text : (thisMonth.length > 0 ? thisMonth[0].review_text : 'No reviews this month');

// Responded to
const responded = thisMonth.filter(r => r.response_posted && r.response_posted !== '').length;

return [{
  json: {
    client_name: client.client_name,
    business_name: client.business_name,
    client_email: client.email,
    fee: client.fee,
    total_new_reviews: thisMonth.length,
    this_month_avg: thisMonthAvg,
    last_month_avg: lastMonthAvg,
    trend: trend,
    reviews_responded: responded,
    best_review: bestReview,
    report_month: today.toLocaleString('en-GB', { month: 'long', year: 'numeric' }),
    all_reviews_this_month: thisMonth
  }
}];

